Node *push_front(Node *head, int v) {
  Node *n = malloc(sizeof *n);
  if (!n) return head;
  n->data = v; n->next = head;
  return n;
}

typedef struct { int *a; int top, cap; } Stack;
void push(Stack *s, int v) { if (s->top < s->cap) s->a[s->top++] = v; }
int pop(Stack *s) { return s->top ? s->a[--s->top] : -1; }

