#include <stdio.h>
#include <string.h>
int main(void) {
    char s[] = "([]{})";
    char st[32]; int top = 0, ok = 1;
    for (int i = 0; s[i] && ok; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') st[top++] = c;
        else if (c == ')' || c == ']' || c == '}') {
            if (!top) ok = 0;
            else {
                char o = st[--top];
                if ((c == ')' && o != '(') || (c == ']' && o != '[') || (c == '}' && o != '{')) ok = 0;
            }
        }
    }
    printf("%s\n", ok && top == 0 ? "balanced" : "not balanced");
    return 0;
}

